function validScriptUrl(v){return /^https:\/\/script\.google\.com\/macros\/s\/[-\w]+\/exec$/.test(v||'');}
async function saveSettings(notify=true){
 if(!cloud.hosted()) {const url=$('#script-url').value.trim();if(!validScriptUrl(url))throw Error('ใช้ลิงก์ https://script.google.com/macros/s/.../exec');settings.scriptUrl=url;}
 else {const sheetId=safeId($('#sheet-id').value);if(settings.sheetId&&settings.sheetId!==sheetId&&products.some(p=>!p.demo))throw Error('มีข้อมูลของชีตเดิมอยู่ กรุณาใช้เบราว์เซอร์แยกสำหรับชีตใหม่');if(settings.sheetId!==sheetId)cloud.disconnect();settings.sheetId=sheetId;}
 delete settings.clientId;await db.put('settings',settings);cloud.configure(settings);updateConnection();if(notify)toast('บันทึกการตั้งค่าแล้ว');
}
function exportCSV(){const rows=[['Item Code','Product Name','Purpose','Required angles','Photos','Status','Google sync'],...products.map(p=>[p.code,p.name,p.purpose,progress(p).required,progress(p).total,status(p),p.dirty?'Local draft':'Saved'])];const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='PIM-Photo-Report-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'เกิดข้อผิดพลาด กรุณาลองใหม่',true);});
await (async()=>{settings=await db.get('settings','config')||settings;brand=await db.get('settings','branding')||brand;workspace=await db.get('settings','workspace-cache')||workspace;lastSync=workspace.at||'';applyBranding();cloud.configure(settings);await route();if(true){try{await cloud.connect(settings);updateConnection();await refreshCloud(true);if(location.hash==='#settings')renderSettings();else if(current)renderDetail();}catch(e){toast(e.message,true);}}})();


