function openReportPicker(only){
 const eligible=(only||products).filter(p=>progress(p).total>0);

 openModal(modalHeader('Export PDF')+'<div class="modal-body"><p class="subtext">เลือกไฟล์นำเข้า แล้วเลือกทั้งไฟล์หรือเฉพาะ Item ที่ต้องการ<br>จัดหน้า A4 พร้อมรายละเอียด ภาพทุกมุม และลิงก์ Drive ที่กดได้</p><div class="report-controls"><label>ไฟล์นำเข้า<select id="report-batch"><option value="">ทุกไฟล์</option>'+batches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>ขอบเขต<select id="report-scope"><option value="selected">เลือก Item</option><option value="all">ทั้งไฟล์ (รายการที่มีรูป)</option></select></label></div><p id="report-empty" class="notice" hidden>ไฟล์นี้ยังไม่มีรายการที่มีรูป กรุณาถ่ายรูปก่อนส่งออก PDF</p><div class="report-options">'+eligible.map((p,i)=>'<label class="report-choice"><input type="checkbox" data-report-id="'+p.id+'" '+(i===0?'checked':'')+'><span><b>'+esc(p.code)+'</b> · '+esc(p.name)+'<small>'+progress(p).total+' รูป · Revision '+(p.revisionNumber||'ฉบับร่าง')+' · '+progress(p).required+'/7 มุมบังคับ'+(p.dirty||!p.syncedAt?' · ฉบับร่าง':'')+'</small></span></label>').join('')+'</div><button id="make-pdf" class="primary">'+icon('file')+'สร้าง PDF</button></div>');
 const updateReport=()=>{const batch=$('#report-batch').value;modal.querySelectorAll('[data-report-id]').forEach(input=>{const p=eligible.find(p=>p.id===input.dataset.reportId);input.closest('label').hidden=!!batch&&p.importId!==batch;});const count=eligible.filter(p=>!batch||p.importId===batch).length;$('#report-empty').hidden=count>0;$('#make-pdf').disabled=!count;};$('#report-batch').onchange=updateReport;updateReport();
 $('#make-pdf').onclick=()=>run(async()=>{
  const ids=[...modal.querySelectorAll('[data-report-id]:checked')].map(x=>x.dataset.reportId),chosen=eligible.filter(p=>(!$('#report-batch').value||p.importId===$('#report-batch').value)&&($('#report-scope').value==='all'||ids.includes(p.id)));if(!chosen.length)throw Error('เลือกอย่างน้อย 1 รายการ');
  $('#make-pdf').disabled=true;try{const {createPhotoReport}=await import('./pdf.mjs');const report=await createPhotoReport(chosen,photoUrl,busy);clearReport();const url=URL.createObjectURL(report.blob);reportUrls.push(url);const previews=report.pages.map(p=>{const u=URL.createObjectURL(p);reportUrls.push(u);return u;});openModal(modalHeader('PDF พร้อมดาวน์โหลด')+'<div class="modal-body"><div class="actions" style="margin-bottom:16px"><a class="pdf-download" href="'+url+'" download="'+esc(report.filename)+'">'+icon('export')+'ดาวน์โหลด PDF</a><span class="help">'+report.pages.length+' หน้า · '+size(report.blob.size)+'</span></div><div class="pdf-preview">'+previews.map((u,i)=>'<img src="'+u+'" alt="ตัวอย่าง PDF หน้า '+(i+1)+'">').join('')+'</div></div>');}finally{if($('#make-pdf'))$('#make-pdf').disabled=false;}
 });
}

function choiceControl(kind,value){const values=[...new Set([...workspace.options.filter(r=>r[0]===kind).map(r=>r[1]),...(value?[value]:[])])];return '<span class="choice-control"><select id="'+kind+'" '+(kind==='remark'?'data-field="remark"':'')+'><option value="">เลือก'+(kind==='remark'?' Remark':'ชื่อผู้ถ่าย')+'</option>'+values.map(v=>'<option '+(v===value?'selected':'')+' value="'+esc(v)+'">'+esc(v)+'</option>').join('')+'</select><button type="button" data-option-add="'+kind+'" aria-label="เพิ่ม '+kind+'">+</button><button type="button" data-option-remove="'+kind+'" aria-label="ลบตัวเลือก '+kind+'">−</button></span>';}
function bindChoices(){main.querySelectorAll('[data-option-add],[data-option-remove]').forEach(b=>b.onclick=()=>{const kind=b.dataset.optionAdd||b.dataset.optionRemove,remove=!!b.dataset.optionRemove,value=$('#'+kind).value;if(remove&&!value)return;openModal(modalHeader(remove?'ลบตัวเลือกจากรายการร่วม':'เพิ่มตัวเลือกสำหรับทุกเครื่อง')+'<div class="modal-body"><p>ตัวเลือกนี้ใช้ร่วมกันทุกเครื่อง การลบไม่เปลี่ยนข้อมูลที่เคยบันทึก</p><input id="option-value" maxlength="500" value="'+esc(remove?value:'')+'" '+(remove?'readonly':'')+'><button id="option-save" class="primary">'+(remove?'ลบตัวเลือก':'บันทึก')+'</button></div>');$('#option-save').onclick=()=>run(async()=>{if(!cloud.connected())throw Error('เชื่อมต่อ Google ก่อน');workspace.options=await cloud.changeOption(kind,$('#option-value').value,remove?'remove':'add');await saveDraft();closeModal();renderDetail();});});}
function listMetadata(p){const d=workspace.data.find(d=>d.id===p.id),key=v=>String(v||'').trim().toUpperCase(),stock=workspace.stock.rows.filter(r=>key(r.code)===key(p.code));return '<div class="help">'+([...new Set(stock.map(r=>r.company+' · '+r.location))].map(esc).join('<br>')||'—')+'</div>';}

function summaryRows(){return products.filter(p=>!p.demo).map(p=>{const d=workspace.data.find(d=>d.id===p.id),raw=d?.requestDate||'',m=raw.match(/^(\d{2})\/(\d{2})\/(\d{4})/),day=summaryFilter.date==='request'?(m?m[3]+'-'+m[2]+'-'+m[1]:raw.slice(0,10)):new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(p.createdAt));return {...p,requester:d?.requester||'ไม่ระบุ',day};}).filter(p=>(!summaryFilter.file||p.importId===summaryFilter.file)&&(!summaryFilter.requester||p.requester===summaryFilter.requester)&&(!summaryFilter.status||status(p)===summaryFilter.status)&&(!summaryFilter.from||p.day>=summaryFilter.from)&&(!summaryFilter.to||p.day<=summaryFilter.to));}
function renderSummary(){
 const rows=summaryRows(),days=new Map(),people=new Map(),counts={waiting:0,progress:0,complete:0};for(const p of rows){if(/^\d{4}-\d{2}-\d{2}$/.test(p.day))days.set(p.day,(days.get(p.day)||0)+1);people.set(p.requester,(people.get(p.requester)||0)+1);counts[status(p)]++;}
 const daily=[...days].sort((a,b)=>a[0].localeCompare(b[0])),ranking=[...people].sort((a,b)=>b[1]-a[1]),max=Math.max(1,...daily.map(x=>x[1])),top=Math.max(1,...ranking.map(x=>x[1])),done=rows.length?Math.round(counts.complete/rows.length*100):0;
 const options=(items,value)=>'<option value="">ทั้งหมด</option>'+items.map(([id,label])=>'<option value="'+esc(id)+'" '+(id===value?'selected':'')+'>'+esc(label)+'</option>').join('');
 main.innerHTML=title('WORKSPACE INSIGHTS','ภาพรวมงานถ่ายรูป','นับงานเป็นรายการสินค้าในแต่ละไฟล์นำเข้า · อัปเดต '+fmtDate(lastSync))+'<section class="panel insight-filters"><label class="field">นับตามวันที่<select data-summary="date"><option value="import" '+(summaryFilter.date==='import'?'selected':'')+'>วันที่นำเข้าระบบ</option><option value="request" '+(summaryFilter.date==='request'?'selected':'')+'>วันที่ขอรูป</option></select></label><label class="field">ตั้งแต่<input type="date" data-summary="from" value="'+summaryFilter.from+'"></label><label class="field">ถึง<input type="date" data-summary="to" value="'+summaryFilter.to+'"></label><label class="field">ไฟล์นำเข้า<select data-summary="file">'+options(batches.map(b=>[b.id,b.name]),summaryFilter.file)+'</select></label><label class="field">ผู้ขอรูป<select data-summary="requester">'+options([...new Set(workspace.data.map(d=>d.requester||'ไม่ระบุ'))].sort().map(v=>[v,v]),summaryFilter.requester)+'</select></label><label class="field">สถานะ<select data-summary="status">'+options([['waiting','รอถ่าย'],['progress','กำลังถ่าย'],['complete','ครบแล้ว']],summaryFilter.status)+'</select></label><button id="reset-summary">ล้างตัวกรอง</button></section><div class="insight-metrics">'+[['งานทั้งหมด',rows.length,'blue'],['ภาพทั้งหมด',rows.reduce((n,p)=>n+progress(p).total,0),'purple'],['ถ่ายครบแล้ว',counts.complete,'green'],['ผู้ขอรูป',people.size,'orange']].map(([label,n,c])=>'<article class="panel metric '+c+'"><small>'+label+'</small><strong>'+n+'</strong></article>').join('')+'</div><div class="insight-grid"><section class="panel chart-panel"><h2>งานในแต่ละวัน</h2><p class="help">จำนวนรายการสินค้า · '+(summaryFilter.date==='import'?'วันที่นำเข้าระบบ':'วันที่ขอรูป')+'</p><div class="daily-chart" role="img" aria-label="กราฟจำนวนงานรายวัน">'+(daily.length?daily.map(([day,n])=>'<div class="day-column" title="'+day+' : '+n+' งาน"><b>'+n+'</b><div class="bar-track"><i style="height:'+Math.max(3,n/max*100)+'%"></i></div><span>'+day.slice(8)+'/'+day.slice(5,7)+'<small>'+day.slice(0,4)+'</small></span></div>').join(''):'<p class="empty-chart">ไม่มีงานในช่วงที่เลือก</p>')+'</div><div class="chart-foot"><span>วันที่มีงาน <b>'+daily.length+' วัน</b></span><span>สูงสุดต่อวัน <b>'+(daily.length?max:0)+' งาน</b></span></div></section><section class="panel chart-panel"><h2>ใครขอรูปมากที่สุด</h2><p class="help">เรียงตามจำนวนรายการที่ขอ</p><div class="ranking-chart">'+(ranking.length?ranking.map(([name,n],i)=>'<div class="rank-row"><div><span>'+String(i+1).padStart(2,'0')+' · '+esc(name)+'</span><b>'+n+' งาน · '+Math.round(n/Math.max(1,rows.length)*100)+'%</b></div><div class="rank-track"><i style="width:'+n/top*100+'%"></i></div></div>').join(''):'<p class="empty-chart">ไม่มีข้อมูลตามตัวกรอง</p>')+'</div></section><section class="panel chart-panel status-panel"><div><h2>ความคืบหน้าของงาน</h2><p class="help">รวมฉบับร่างในเครื่องนี้ด้วย</p><div class="status-legend">'+[['waiting','รอถ่าย'],['progress','กำลังถ่าย'],['complete','ครบแล้ว']].map(([s,label])=>'<p><span>'+label+'</span><b>'+counts[s]+'</b></p>').join('')+'</div></div><div class="completion-ring" style="--done:'+done+'%"><div><strong>'+done+'%</strong><span>ถ่ายครบแล้ว</span></div></div></section></div>';
 main.insertAdjacentHTML('beforeend',summaryQueue(rows));
 main.querySelectorAll('[data-summary]').forEach(el=>el.onchange=()=>{summaryFilter[el.dataset.summary]=el.value;renderSummary();});$('#reset-summary').onclick=()=>{summaryFilter={file:'',requester:'',status:'',from:'',to:'',date:'import'};renderSummary();};
}

