async function hydrateListPhotos(){for(const img of main.querySelectorAll('[data-list-product]')){const p=products.find(p=>p.id===img.dataset.listProduct),photo=p?.photos?.top?.[0];if(!photo)continue;try{const url=await photoUrl(photo);if(img.isConnected&&url)img.src=url;}catch{if(img.isConnected)img.alt='โหลดภาพไม่สำเร็จ';}}}

function renderSaveBar(){
 main.insertAdjacentHTML('beforeend','<div class="save-dock"><div><b>ฉบับร่างบันทึกอัตโนมัติ</b><small>บันทึกลง Google เพื่อให้ทุกเครื่องเห็นข้อมูลและรูปชุดนี้</small></div><button class="primary" id="save-cloud">'+icon('cloud')+'บันทึกลง Google</button></div>');
 $('#save-cloud').onclick=()=>run(saveCloud);
}
function applyBranding(){
 const el=document.querySelector('.brand');if(!el)return;
 el.innerHTML='<span class="brand-icon">'+(brand.logo?'<img src="'+esc(brand.logo)+'" alt="โลโก้">':icon('box'))+'</span><span><strong>'+esc(brand.name)+'</strong><small>'+esc(brand.subtitle)+'</small></span>';
 document.title=brand.name+' · '+brand.subtitle;document.querySelector('.topbar-label b').textContent=brand.name;
}
function brandingPanel(){return '<section class="panel"><div class="panel-head"><h2>ชื่อและโลโก้ของพื้นที่ทำงาน</h2><span class="badge neutral">ใช้ร่วมกันทุกเครื่อง</span></div><div class="panel-body branding-editor"><div class="brand-preview">'+(brand.logo?'<img id="brand-preview" src="'+esc(brand.logo)+'" alt="โลโก้ปัจจุบัน">':'<img id="brand-preview" hidden alt="ตัวอย่างโลโก้">')+'<label class="upload-brand">เลือกโลโก้<input id="brand-file" type="file" accept="image/png,image/jpeg,image/webp"></label><button id="brand-remove" class="ghost small">นำโลโก้ออก</button></div><div><label class="field">ชื่อแอป / ทีม<input id="brand-name" maxlength="60" value="'+esc(brand.name)+'"></label><label class="field">คำอธิบายใต้ชื่อ<input id="brand-subtitle" maxlength="80" value="'+esc(brand.subtitle)+'"></label><p class="help">PNG, JPG, WebP · โลโก้จะปรับขนาดให้เหมาะกับหน้าจอ การเปลี่ยนแปลงจะปรากฏทุกเครื่องเมื่อซิงก์</p><button class="primary" id="brand-save">บันทึกชื่อและโลโก้</button></div></div></section>';}
function bindBranding(){
 let logo=brand.logo;$('#brand-file').onchange=()=>run(async()=>{const f=$('#brand-file').files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5*1024*1024)throw Error('เลือก PNG, JPG หรือ WebP ไม่เกิน 5 MB');const bitmap=await createImageBitmap(f),ratio=Math.min(1,320/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();logo=canvas.toDataURL('image/webp',.9);if(logo.length>180000)throw Error('โลโก้มีขนาดใหญ่เกินไป');$('#brand-preview').src=logo;$('#brand-preview').hidden=false;});
 $('#brand-remove').onclick=()=>{logo='';$('#brand-preview').hidden=true;};
 $('#brand-save').onclick=()=>run(async()=>{if(!cloud.connected())throw Error('เชื่อม Google ก่อนบันทึกการตั้งค่าร่วม');busy('กำลังบันทึกชื่อและโลโก้');brand=await cloud.saveBranding({name:$('#brand-name').value,subtitle:$('#brand-subtitle').value,logo});await db.put('settings',{id:'branding',...brand});applyBranding();toast('บันทึกแล้ว ทุกเครื่องจะเห็นเมื่อซิงก์');});
}

function summaryQueue(rows){
 const pending=rows.filter(p=>status(p)!=='complete').sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))),recent=rows.filter(p=>p.syncedAt).sort((a,b)=>b.syncedAt.localeCompare(a.syncedAt)).slice(0,4);
 return '<div class="insight-grid queue-grid"><section class="panel chart-panel"><div class="queue-title"><div><h2>งานที่ต้องทำต่อ</h2><p class="help">เรียงจากงานนำเข้าเก่าสุด · '+pending.length+' งาน</p></div><a href="#products" class="text-link">ดูรายการทั้งหมด →</a></div>'+ (pending.slice(0,5).map(p=>'<a class="queue-row" href="#product/'+p.id+'"><span><b>'+esc(p.code)+'</b><small>'+esc(p.name)+'</small></span><span>'+badge(p)+'<small>'+progress(p).required+'/7 มุม</small></span></a>').join('')||'<p class="empty-chart">ถ่ายครบทุกงานในตัวกรองนี้แล้ว</p>')+'</section><section class="panel chart-panel"><h2>บันทึกล่าสุด</h2><p class="help">ตรวจสอบความคืบหน้าและผู้ถ่าย</p>'+ (recent.map(p=>'<a class="queue-row" href="#product/'+p.id+'"><span><b>'+esc(p.code)+'</b><small>'+esc(p.fields?.photographer||'ไม่ระบุผู้ถ่าย')+'</small></span><span><b>'+progress(p).total+' รูป</b><small>'+fmtDate(p.syncedAt)+'</small></span></a>').join('')||'<p class="empty-chart">ยังไม่มีงานที่บันทึกลง Google ในตัวกรองนี้</p>')+'</section></div>';
}

async function openDeleteImport(batchId){
 const batch=batches.find(b=>b.id===batchId)||(workspace.deletions||[]).find(b=>b.id===batchId);if(!batch)return;
 if(!cloud.connected())return toast('เชื่อม Google ก่อนลบทั้งไฟล์ เพื่อให้ลบข้อมูลครบทุกที่',true);
 openModal(modalHeader('ลบไฟล์นำเข้าและข้อมูลทั้งหมด')+'<div class="modal-body"><p>กำลังตรวจรายการสินค้าและไฟล์ที่เกี่ยวข้อง…</p></div>');
 try{const preview=await cloud.deletePreview(batchId,batch.name);preview.products=Math.max(preview.products,products.filter(p=>p.importId===batchId).length);if(!modal.open)return;
 openModal(modalHeader('ลบไฟล์นำเข้าและข้อมูลทั้งหมด')+'<div class="modal-body"><p><b>'+esc(batch.name)+'</b></p><div class="notice">ลบสินค้า '+preview.products+' รายการออกจากแอปและชีต รวมประวัติ Revision และข้อมูลต้นฉบับของไฟล์นี้<br>ย้ายไฟล์ใน Drive '+preview.files+' ไฟล์ไปถังขยะ'+(preview.shared?'<br>คงรูปที่งานอื่นยังใช้อยู่ '+preview.shared+' ไฟล์ เพื่อไม่ให้งานอื่นเสียหาย':'')+'</div><p class="help">การเปลี่ยนแปลงมีผลทุกเครื่องเมื่อซิงก์ ข้อมูลในชีตใช้ประวัติเวอร์ชันเพื่อกู้คืน ส่วนไฟล์ Drive อยู่ในถังขยะ</p><label class="field">พิมพ์ชื่อไฟล์ด้านบนเพื่อยืนยัน<input id="delete-confirm-name" autocomplete="off"></label><div class="actions" style="margin-top:20px"><button id="cancel-batch-delete">ยกเลิก</button><button id="confirm-batch-delete" class="danger" disabled>ยืนยันลบทั้งไฟล์</button></div><p id="delete-error" role="alert"></p></div>');
 $('#cancel-batch-delete').onclick=closeModal;$('#delete-confirm-name').oninput=()=>$('#confirm-batch-delete').disabled=$('#delete-confirm-name').value!==batch.name;
 $('#confirm-batch-delete').onclick=()=>run(async()=>{const button=$('#confirm-batch-delete');button.disabled=true;try{busy('กำลังลบข้อมูลจากชีตและย้ายไฟล์ Drive ไปถังขยะ');await cloud.deleteImport(batchId,$('#delete-confirm-name').value);await db.deleteBatch(batchId);for(const url of objectUrls.values())URL.revokeObjectURL(url);objectUrls.clear();batchFilter='';page=1;closeModal();await reloadLocal();await refreshCloud(true);location.hash='imports';await route();toast('ลบไฟล์นำเข้าและข้อมูลที่เกี่ยวข้องแล้ว');}catch(e){$('#delete-error').textContent='ยังลบไม่ครบ: '+e.message+' กรุณาลองยืนยันอีกครั้งเพื่อทำต่อ';button.disabled=false;throw e;}});
 }catch(e){closeModal();toast(e.message,true);}
}
